/* Dynamic bidi text enabled and disabled with a root window that has no canvas.

   gx_system_bidi_text_enable and gx_system_bidi_text_disable send an event to
   every root window that has a canvas. Without error checking,
   gx_window_root_create accepts a NULL canvas, and such a root must be passed
   over: a root with a canvas gets one enable and one disable event, the root
   without one gets neither. With error checking, gx_window_root_create refuses
   the NULL canvas. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_system_bidi_text_root_without_canvas_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

UINT gx_validation_graphics_driver_setup_565rgb(GX_DISPLAY *display);

static UINT           failed_tests = 0;

static TX_THREAD      test_thread;
static ULONG          test_thread_stack[8192 / sizeof(ULONG)];

static GX_DISPLAY     test_display;
static GX_CANVAS      test_canvas;
static USHORT         test_memory[32 * 24];
static GX_WINDOW_ROOT test_root;
static GX_WINDOW_ROOT test_root_no_canvas;

/* Enable and disable events each root received.  */
static INT            test_events[2][2];

static UINT test_root_event_process(GX_WINDOW *window, GX_EVENT *event_ptr)
{
INT root = (window == (GX_WINDOW *)&test_root) ? 0 : 1;

    if (event_ptr -> gx_event_type == GX_EVENT_DYNAMIC_BIDI_TEXT_ENABLE)
    {
        test_events[root][0]++;
    }
    else if (event_ptr -> gx_event_type == GX_EVENT_DYNAMIC_BIDI_TEXT_DISABLE)
    {
        test_events[root][1]++;
    }
    return gx_window_root_event_process((GX_WINDOW_ROOT *)window, event_ptr);
}

static VOID test_thread_entry(ULONG id)
{
GX_RECTANGLE size;

    gx_system_initialize();

    EXPECT_EQ(GX_SUCCESS, gx_display_create(&test_display, "test_display", gx_validation_graphics_driver_setup_565rgb, 32, 24));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_canvas, "test_canvas", &test_display, GX_CANVAS_SIMPLE,
                                           32, 24, (GX_COLOR *)test_memory, sizeof(test_memory)));
    gx_utility_rectangle_define(&size, 0, 0, 31, 23);
    EXPECT_EQ(GX_SUCCESS, gx_window_root_create(&test_root, "test_root", &test_canvas, GX_STYLE_NONE, GX_ID_NONE, &size));
    gx_widget_event_process_set(&test_root, test_root_event_process);

#if defined(GX_DISABLE_ERROR_CHECKING)
    EXPECT_EQ(GX_SUCCESS, gx_window_root_create(&test_root_no_canvas, "test_root_no_canvas", GX_NULL, GX_STYLE_NONE, GX_ID_NONE, &size));
    gx_widget_event_process_set(&test_root_no_canvas, test_root_event_process);
#else
    EXPECT_EQ(GX_PTR_ERROR, gx_window_root_create(&test_root_no_canvas, "test_root_no_canvas", GX_NULL, GX_STYLE_NONE, GX_ID_NONE, &size));
#endif

    EXPECT_EQ(GX_SUCCESS, gx_system_bidi_text_enable());
    EXPECT_EQ(GX_SUCCESS, gx_system_bidi_text_disable());

    EXPECT_EQ(1, test_events[0][0]);
    EXPECT_EQ(1, test_events[0][1]);
    EXPECT_EQ(0, test_events[1][0]);
    EXPECT_EQ(0, test_events[1][1]);

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

